      totalPriceSet { shopMoney { amount currencyCode } }
      totalRefundedSet { shopMoney { amount } }
      totalRefundedShippingSet { shopMoney { amount } }
      netPaymentSet { shopMoney { amount } }
      refundable
      shippingLines(first: 5) { nodes { id title code originalPriceSet { shopMoney { amount currencyCode } } taxLines { rate } } }
      lineItems(first: 5) { nodes { id title quantity originalUnitPriceSet { shopMoney { amount } } } }
      fulfillments(first: 5) { id status }
      refunds(first: 5) { id }
      transactions(first: 10) { id kind status gateway test processedAt amountSet { shopMoney { amount currencyCode } } parentTransaction { id } }
    }
  }
}

