mutation MergeCancelSecondary($orderId: ID!, $staffNote: String!) {
  orderCancel(
    orderId: $orderId
    reason: OTHER
    notifyCustomer: false
    restock: true
    refundMethod: { originalPaymentMethodsRefund: false }
    staffNote: $staffNote
  ) {
    job { id }
    orderCancelUserErrors { field message code }
  }
}

query State($id: ID!) {
  order(id: $id) {
    id name test cancelledAt closedAt closed cancelReason displayFinancialStatus displayFulfillmentStatus refundable
    totalRefundedSet { shopMoney { amount currencyCode } }
    totalRefundedShippingSet { shopMoney { amount currencyCode } }
    netPaymentSet { shopMoney { amount } }
    totalOutstandingSet { shopMoney { amount } }
    refunds(first: 20) { id note createdAt processedAt totalRefundedSet { shopMoney { amount currencyCode } }
      refundShippingLines(first: 5) { nodes { id subtotalAmountSet { shopMoney { amount } } taxAmountSet { shopMoney { amount } } shippingLine { id title } } }
